const results = await parallel(batches.map((batch, idx) => () =>
  agent(promptFor(batch, idx), {
    label: `batch ${idx + 1}: ${batch[0].name.slice(0, 26).trim()}`,
    phase: 'Research',
    model: "claude-haiku-4-5-20251001",
  })
));

const ok = results.filter(Boolean).length;
log(`Wave 13 done — ${ok}/${batches.length} batches`);
return { wave: 13, batches_total: batches.length, batches_ok: ok, station_count: STATIONS.length, offset: 19200 };
